[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.1.0/fonts/remixicon.css" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --blue: #3861FB;
  --blue-hover: #2851e8;
  --blue-light: #eef1ff;
  --navy: #0D1421;
  --gray-900: #171924;
  --gray-700: #323546;
  --gray-500: #58667E;
  --gray-400: #808A9D;
  --gray-300: #A6B0C3;
  --gray-200: #CFD6E4;
  --gray-100: #EFF2F5;
  --gray-50: #F8FAFD;
  --white: #FFFFFF;
  --green: #16c784;
  --green-bg: #e6f9f3;
  --red: #ea3943;
  --red-bg: #fde8e9;
  --orange: #f7931a;
  --border: #EFF2F5;
  --shadow: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --radius: 8px;
  --radius-sm: 6px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--gray-50);
  color: var(--navy);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Navigation */
.nav { background: var(--white); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
.nav-inner { max-width: 1400px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; height: 64px; gap: 8px; }
.nav-brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; color: var(--navy); text-decoration: none; margin-right: 8px; }
.nav-brand i { color: var(--blue); font-size: 24px; }
.nav-links { display: flex; align-items: center; gap: 4px; list-style: none; }
.nav-links a { text-decoration: none; color: var(--gray-500); font-size: 14px; font-weight: 500; padding: 8px 12px; border-radius: var(--radius-sm); transition: all 0.15s; white-space: nowrap; }
.nav-links a:hover, .nav-links a.active { color: var(--blue); background: var(--blue-light); }
.nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.nav-right .btn { text-decoration: none; font-size: 14px; font-weight: 600; padding: 8px 20px; border-radius: var(--radius-sm); transition: all 0.15s; }
.btn-login { color: var(--blue); }
.btn-login:hover { background: var(--blue-light); }
.btn-signup { background: var(--blue); color: var(--white); }
.btn-signup:hover { background: var(--blue-hover); }

/* Top Metrics */
.metrics-bar { background: var(--white); border-bottom: 1px solid var(--border); }
.metrics-inner { max-width: 1400px; margin: 0 auto; padding: 16px 24px; display: flex; gap: 32px; flex-wrap: wrap; }
.metric { display: flex; flex-direction: column; gap: 2px; }
.metric-label { font-size: 12px; color: var(--gray-400); font-weight: 500; text-transform: uppercase; letter-spacing: 0.5px; }
.metric-value { font-size: 16px; font-weight: 700; color: var(--navy); font-variant-numeric: tabular-nums; }
.metric-change { font-size: 12px; font-weight: 600; }
.metric-change.up { color: var(--green); }
.metric-change.down { color: var(--red); }
.metric-fg { display: flex; align-items: center; gap: 8px; }
.metric-fg-score { font-size: 20px; font-weight: 700; }
.metric-fg-label { font-size: 12px; color: var(--gray-400); font-weight: 500; }

/* Promo Banner */
.promo { background: linear-gradient(135deg, #3861FB 0%, #5b47fb 100%); color: var(--white); position: relative; overflow: hidden; }
.promo-inner { max-width: 1400px; margin: 0 auto; padding: 12px 24px; display: flex; align-items: center; justify-content: center; gap: 12px; min-height: 48px; }
.promo-slide { display: none; align-items: center; gap: 12px; font-size: 14px; font-weight: 500; }
.promo-slide.active { display: flex; }
.promo-arrow { background: rgba(255,255,255,0.2); border: none; color: white; width: 28px; height: 28px; border-radius: 50%; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 14px; transition: background 0.15s; }
.promo-arrow:hover { background: rgba(255,255,255,0.35); }
.promo-dots { display: flex; gap: 6px; margin-left: 8px; }
.promo-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(255,255,255,0.4); cursor: pointer; transition: all 0.15s; }
.promo-dot.active { background: white; width: 18px; border-radius: 3px; }

/* AI Alerts */
.ai-bar { background: var(--white); border-bottom: 1px solid var(--border); }
.ai-inner { max-width: 1400px; margin: 0 auto; padding: 12px 24px; display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.ai-prompt { display: flex; align-items: center; gap: 8px; background: var(--gray-50); border: 1px solid var(--border); border-radius: 20px; padding: 8px 16px; font-size: 13px; color: var(--gray-500); cursor: pointer; transition: all 0.15s; }
.ai-prompt:hover { border-color: var(--blue); color: var(--blue); }
.ai-prompt i { font-size: 16px; color: var(--blue); }
.ai-quick { display: flex; gap: 8px; flex-wrap: wrap; }
.ai-chip { font-size: 12px; color: var(--gray-500); background: var(--gray-50); border: 1px solid var(--border); border-radius: 16px; padding: 4px 12px; cursor: pointer; white-space: nowrap; transition: all 0.15s; }
.ai-chip:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

/* Main Content */
.main { max-width: 1400px; margin: 0 auto; padding: 0 24px; }

/* Tabs Row */
.tabs-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 0 8px; flex-wrap: wrap; }
.network-tabs { display: flex; gap: 4px; }
.network-tab { font-size: 13px; font-weight: 500; padding: 6px 14px; border-radius: 20px; border: 1px solid var(--border); background: var(--white); color: var(--gray-500); cursor: pointer; transition: all 0.15s; }
.network-tab:hover { border-color: var(--blue); color: var(--blue); }
.network-tab.active { background: var(--blue); color: white; border-color: var(--blue); }

.category-tabs { display: flex; gap: 4px; flex-wrap: wrap; }
.category-tab { font-size: 13px; font-weight: 500; padding: 8px 16px; border-radius: var(--radius-sm); border: none; background: transparent; color: var(--gray-500); cursor: pointer; transition: all 0.15s; }
.category-tab:hover { color: var(--navy); background: var(--gray-100); }
.category-tab.active { color: var(--blue); background: var(--blue-light); font-weight: 600; }

/* Table Controls */
.table-controls { display: flex; align-items: center; gap: 8px; padding: 8px 0; position: relative; }
.table-sort { font-size: 13px; color: var(--gray-500); padding: 6px 12px; border-radius: var(--radius-sm); border: 1px solid var(--border); background: var(--white); cursor: pointer; display: flex; align-items: center; gap: 4px; font-weight: 500; }
.table-sort:hover { border-color: var(--gray-300); }
.control-btn { font-size: 13px; font-weight: 500; padding: 6px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border); background: var(--white); color: var(--gray-500); cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.15s; }
.control-btn:hover { border-color: var(--gray-300); color: var(--navy); }
.control-btn.active { background: var(--blue); color: white; border-color: var(--blue); }

/* Dropdown */
.dropdown { position: absolute; top: 100%; left: 0; margin-top: 4px; background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-md); padding: 12px; z-index: 50; min-width: 200px; display: none; }
.dropdown.show { display: block; }
.dropdown-item { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px; color: var(--gray-700); cursor: pointer; }
.dropdown-item:hover { background: var(--gray-50); }
.dropdown-item input[type=checkbox] { accent-color: var(--blue); }

/* Filters Panel */
.filters-panel { display: none; background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-md); padding: 20px; margin-bottom: 12px; }
.filters-panel.show { display: block; }
.filters-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.filter-group { display: flex; flex-direction: column; gap: 4px; }
.filter-label { font-size: 12px; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.3px; }
.filter-input { padding: 8px 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); font-size: 14px; font-family: inherit; }
.filter-input:focus { outline: none; border-color: var(--blue); box-shadow: 0 0 0 3px rgba(56,97,251,0.1); }
.filter-select { padding: 8px 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); font-size: 14px; font-family: inherit; background: white; }

/* Table */
.table-wrap { background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); }
.table-scroll { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
thead th { font-size: 12px; font-weight: 600; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.5px; padding: 12px 16px; border-bottom: 2px solid var(--border); background: var(--gray-50); white-space: nowrap; text-align: right; cursor: pointer; user-select: none; }
thead th:first-child { text-align: center; }
thead th:nth-child(2) { text-align: left; }
thead th:hover { color: var(--navy); }
thead th .sort-icon { font-size: 10px; margin-left: 2px; opacity: 0.4; }
thead th.sorted .sort-icon { opacity: 1; color: var(--blue); }
tbody td { padding: 14px 16px; border-bottom: 1px solid var(--border); font-size: 14px; text-align: right; white-space: nowrap; }
tbody td:first-child { text-align: center; color: var(--gray-400); font-size: 13px; font-weight: 500; width: 48px; }
tbody td:nth-child(2) { text-align: left; }
tbody tr:hover { background: var(--gray-50); }
tbody tr:last-child td { border-bottom: none; }

.coin-info { display: flex; align-items: center; gap: 10px; }
.coin-icon { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: white; flex-shrink: 0; }
.coin-name { font-weight: 600; color: var(--navy); font-size: 14px; }
.coin-symbol { font-size: 13px; color: var(--gray-400); margin-left: 4px; }
.price { font-weight: 600; color: var(--navy); }
.change { font-weight: 600; font-size: 13px; }
.change.up { color: var(--green); }
.change.down { color: var(--red); }
.mcap, .vol { font-weight: 500; color: var(--navy); }
.supply { font-size: 13px; color: var(--gray-500); }
.sparkline-cell { padding: 8px 16px !important; width: 140px; }
.sparkline-svg { width: 120px; height: 32px; }
.sparkline-svg polyline { fill: none; stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.sparkline-svg polyline.up { stroke: var(--green); }
.sparkline-svg polyline.down { stroke: var(--red); }

/* Index Row */
.index-row td { background: var(--blue-light); border-bottom: 2px solid rgba(56,97,251,0.15); }
.index-row .coin-name { color: var(--blue); }

/* Pagination */
.pagination { display: flex; align-items: center; justify-content: center; gap: 4px; padding: 20px 24px; flex-wrap: wrap; }
.page-btn { min-width: 36px; height: 36px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--white); color: var(--gray-500); font-size: 14px; font-weight: 500; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.15s; }
.page-btn:hover { border-color: var(--blue); color: var(--blue); }
.page-btn.active { background: var(--blue); color: white; border-color: var(--blue); }
.page-btn:disabled { opacity: 0.4; cursor: default; }
.page-info { font-size: 13px; color: var(--gray-400); margin: 0 12px; }

/* Market Summary */
.market-summary { margin-top: 24px; background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); }
.market-summary h3 { font-size: 16px; font-weight: 700; margin-bottom: 12px; color: var(--navy); }
.market-summary p { font-size: 14px; color: var(--gray-500); line-height: 1.7; }
.market-summary .read-more { display: inline-block; margin-top: 12px; color: var(--blue); font-weight: 600; font-size: 14px; cursor: pointer; border: none; background: none; }
.market-summary .read-more:hover { text-decoration: underline; }
.market-summary .more-content { display: none; margin-top: 12px; }
.market-summary .more-content.show { display: block; }
.ms-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px; margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border); }
.ms-stat-label { font-size: 12px; color: var(--gray-400); text-transform: uppercase; letter-spacing: 0.3px; }
.ms-stat-value { font-size: 18px; font-weight: 700; color: var(--navy); font-variant-numeric: tabular-nums; }

/* Info Content */
.info-content { margin-top: 24px; display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; margin-bottom: 40px; }
.info-card { background: var(--white); border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow); }
.info-card h3 { font-size: 15px; font-weight: 700; margin-bottom: 8px; color: var(--navy); }
.info-card p { font-size: 14px; color: var(--gray-500); line-height: 1.7; }

/* Footer */
.footer { background: var(--white); border-top: 1px solid var(--border); margin-top: 40px; padding: 40px 0 24px; }
.footer-inner { max-width: 1400px; margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 32px; }
.footer-col h4 { font-size: 13px; font-weight: 700; color: var(--navy); margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: 13px; color: var(--gray-500); text-decoration: none; padding: 4px 0; transition: color 0.15s; }
.footer-col a:hover { color: var(--blue); }
.footer-bottom { max-width: 1400px; margin: 0 auto; padding: 16px 24px 0; border-top: 1px solid var(--border); margin-top: 24px; text-align: center; font-size: 13px; color: var(--gray-400); }

/* Responsive */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .tabs-row { flex-direction: column; align-items: flex-start; }
  .metrics-inner { gap: 16px; }
}
@media (max-width: 768px) {
  .ai-quick { display: none; }
  .network-tabs { overflow-x: auto; width: 100%; padding-bottom: 4px; }
  .category-tabs { overflow-x: auto; width: 100%; padding-bottom: 4px; }
}
</style>
</head>
