function seedRand(s) { let h=0; for(let i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;} return Math.abs(h)/2147483647; }

function genSparkline(symbol, d7change) {
  const seed = seedRand(symbol);
  const points = [];
  const base = 16;
  const range = 12;
  let val = 10 + seed * 8;
  const trend = d7change > 0 ? 1 : -1;
  for (let i = 0; i < 7; i++) {
    const r = (seedRand(symbol + i) - 0.5) * range;
    val = Math.max(4, Math.min(28, val + r + trend * (Math.abs(d7change) * 0.3)));
    points.push(val);
  }
  // Adjust last point to reflect overall change
  const startVal = points[0];
  const targetEnd = startVal * (1 + d7change / 100);
  points[6] = Math.max(4, Math.min(28, targetEnd * (base / startVal)));
  return points.map(p => (32 - p).toFixed(1)).join(',');
}

