  rank: true, name: true, price: true, change1h: true, change24h: true,
  change7d: true, marketCap: true, volume: true, supply: true, sparkline: true
};

// ── Filters ─────────────────────────────────────────────────
let priceFilter = null;
let changeFilter = null;

// ── Formatting ──────────────────────────────────────────────
function fmtNum(n, decimals) {
  if (n == null) return '—';
  decimals = decimals !== undefined ? decimals : (Math.abs(n) >= 1 ? 2 : (Math.abs(n) >= 0.01 ? 4 : 6));
  return n.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function fmtCompact(n) {
  if (n >= 1e12) return '$' + (n / 1e12).toFixed(2) + 'T';
  if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
  return '$' + fmtNum(n);
}

function fmtSupply(n, sym) {
  if (n >= 1e12) return (n / 1e12).toFixed(2) + 'T ' + sym;
  if (n >= 1e9) return (n / 1e9).toFixed(2) + 'B ' + sym;
  if (n >= 1e6) return (n / 1e6).toFixed(2) + 'M ' + sym;
  return fmtNum(n, 0) + ' ' + sym;
}

function fmtChange(v) {
  const cls = v >= 0 ? 'up' : 'down';
  const sign = v >= 0 ? '+' : '';
  return `<span class="change ${cls}">${sign}${v.toFixed(2)}%</span>`;
}

// ── Filtering ───────────────────────────────────────────────
function getFilteredCoins() {
  let filtered = [...coins];
  if (activeCategory !== 'top') {
    filtered = filtered.filter(c => {
      if (activeCategory === 'trending') return c.category === 'trending';
      if (activeCategory === 'watchlist') return c.rank % 5 === 0 || c.category === 'watchlist';
      if (activeCategory === 'prediction') return c.category === 'prediction';
      if (activeCategory === 'visited') return c.category === 'visited' || c.rank % 7 === 0;
      if (activeCategory === 'new') return c.category === 'new' || c.rank > 80;
      if (activeCategory === 'more') return c.rank % 3 === 0;
      return true;
    });
  }
  if (activeNetwork !== 'all') {
    filtered = filtered.filter(c => c.network === activeNetwork || (activeNetwork === 'more' && !['ethereum','solana','bsc','base'].includes(c.network)));
  }
  if (priceFilter) {
    if (priceFilter.min != null && priceFilter.min !== '') filtered = filtered.filter(c => c.price >= +priceFilter.min);
    if (priceFilter.max != null && priceFilter.max !== '') filtered = filtered.filter(c => c.price <= +priceFilter.max);
  }
  if (changeFilter) {
    if (changeFilter === 'up') filtered = filtered.filter(c => c.change24h >= 0);
    if (changeFilter === 'down') filtered = filtered.filter(c => c.change24h < 0);
    if (changeFilter === 'gt5') filtered = filtered.filter(c => c.change24h >= 5);
    if (changeFilter === 'lt5') filtered = filtered.filter(c => c.change24h <= -5);
  }
  // Sort
  filtered.sort((a, b) => {
    let va = a[activeSort.field];
    let vb = b[activeSort.field];
    if (activeSort.field === 'name') { va = a.name.toLowerCase(); vb = b.name.toLowerCase(); }
    if (activeSort.field === 'supply') { va = a.circulatingSupply; vb = b.circulatingSupply; }
    if (va < vb) return activeSort.dir === 'asc' ? -1 : 1;
    if (va > vb) return activeSort.dir === 'asc' ? 1 : -1;
    return 0;
  });
  // Re-rank
  filtered.forEach((c, i) => c.displayRank = i + 1);
  return filtered;
}

// ── Render Table ────────────────────────────────────────────
function renderSparklineSVG(points, isUp) {
  const cls = isUp ? 'up' : 'down';
  return `<svg class="sparkline-svg" viewBox="0 0 120 32" preserveAspectRatio="none">
    <polyline class="${cls}" points="0,${points.split(',')[0]} 20,${points.split(',')[1]} 40,${points.split(',')[2]} 60,${points.split(',')[3]} 80,${points.split(',')[4]} 100,${points.split(',')[5]} 120,${points.split(',')[6]}" />
  </svg>`;
}

function renderTable() {
  const filtered = getFilteredCoins();
