    <td>${fmtChange(0.21)}</td>
    <td>${fmtChange(1.15)}</td>
    <td>${fmtChange(4.97)}</td>
    <td class="mcap">—</td>
    <td class="vol">—</td>
    <td class="supply">—</td>
    <td class="sparkline-cell"></td>
  </tr>`;

  // Coin rows
  page.forEach(c => {
    const coinBg = c.color;
    html += '<tr>';
    if (columnVisibility.rank) html += `<td>${c.displayRank}</td>`;
    if (columnVisibility.name) html += `<td><div class="coin-info"><div class="coin-icon" style="background:${coinBg}">${c.symbol.slice(0,2)}</div><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.symbol}</span></div></td>`;
    if (columnVisibility.price) html += `<td class="price">$${fmtNum(c.price, c.price < 0.01 ? 6 : c.price < 1 ? 4 : 2)}</td>`;
    if (columnVisibility.change1h) html += `<td>${fmtChange(c.change1h)}</td>`;
    if (columnVisibility.change24h) html += `<td>${fmtChange(c.change24h)}</td>`;
    if (columnVisibility.change7d) html += `<td>${fmtChange(c.change7d)}</td>`;
    if (columnVisibility.marketCap) html += `<td class="mcap">${fmtCompact(c.marketCap)}</td>`;
    if (columnVisibility.volume) html += `<td class="vol">${fmtCompact(c.volume)}</td>`;
    if (columnVisibility.supply) html += `<td class="supply">${fmtSupply(c.circulatingSupply, c.supplySymbol)}</td>`;
    if (columnVisibility.sparkline) html += `<td class="sparkline-cell">${renderSparklineSVG(c.sparkline, c.change7d >= 0)}</td>`;
    html += '</tr>';
  });

  tbody.innerHTML = html;
  renderPagination(filtered.length);
  updateColumnHeaders();
}

function renderPagination(totalItems) {
  const totalPages = Math.ceil(totalItems / rowsPerPage);
  const el = document.getElementById('pagination');
  let html = '';
  html += `<button class="page-btn" onclick="goPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled' : ''}><i class="ri-arrow-left-s-line"></i></button>`;

  const maxBtns = 7;
  let startP = Math.max(1, currentPage - 3);
  let endP = Math.min(totalPages, startP + maxBtns - 1);
  if (endP - startP < maxBtns - 1) startP = Math.max(1, endP - maxBtns + 1);

  if (startP > 1) { html += `<button class="page-btn" onclick="goPage(1)">1</button>`; if (startP > 2) html += `<span class="page-info">…</span>`; }
  for (let i = startP; i <= endP; i++) {
    html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="goPage(${i})">${i}</button>`;
  }
  if (endP < totalPages) { if (endP < totalPages - 1) html += `<span class="page-info">…</span>`; html += `<button class="page-btn" onclick="goPage(${totalPages})">${totalPages}</button>`; }

  html += `<button class="page-btn" onclick="goPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled' : ''}><i class="ri-arrow-right-s-line"></i></button>`;
  html += `<span class="page-info">Showing ${Math.min((currentPage-1)*rowsPerPage+1, totalItems)}–${Math.min(currentPage*rowsPerPage, totalItems)} of ${totalItems.toLocaleString()} assets</span>`;
  el.innerHTML = html;
}

function updateColumnHeaders() {
  const ths = document.querySelectorAll('thead th');
  const cols = ['rank','name','price','change1h','change24h','change7d','marketCap','volume','supply','sparkline'];
  ths.forEach((th, i) => {
    if (i < cols.length) {
      th.style.display = columnVisibility[cols[i]] ? '' : 'none';
    }
  });
}

function goPage(p) {
  const filtered = getFilteredCoins();
  const totalPages = Math.ceil(filtered.length / rowsPerPage);
  if (p < 1 || p > totalPages) return;
  currentPage = p;
  renderTable();
  document.querySelector('.table-wrap').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// ── Tab Handlers ────────────────────────────────────────────
document.getElementById('categoryTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('category-tab')) {
    this.querySelectorAll('.category-tab').forEach(b => b.classList.remove('active'));
    e.target.classList.add('active');
    activeCategory = e.target.dataset.category;
    currentPage = 1;
    renderTable();
  }
});

document.getElementById('networkTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('network-tab')) {
    this.querySelectorAll('.network-tab').forEach(b => b.classList.remove('active'));
    e.target.classList.add('active');
    activeNetwork = e.target.dataset.network;
    currentPage = 1;
    renderTable();
  }
});

// ── Sort Headers ────────────────────────────────────────────
document.querySelector('thead').addEventListener('click', function(e) {
  const th = e.target.closest('th');
  if (!th) return;
  const field = th.dataset.sort;
  if (!field) return;
  if (activeSort.field === field) {
    activeSort.dir = activeSort.dir === 'asc' ? 'desc' : 'asc';
  } else {
    activeSort.field = field;
    activeSort.dir = 'asc';
  }
  document.querySelectorAll('thead th').forEach(h => h.classList.remove('sorted'));
  th.classList.add('sorted');
  th.querySelector('.sort-icon').innerHTML = activeSort.dir === 'asc' ? '&#9650;' : '&#9660;';
  currentPage = 1;
  renderTable();
});

// ── Columns Dropdown ────────────────────────────────────────
document.getElementById('columnsBtn').addEventListener('click', function(e) {
  e.stopPropagation();
  const dd = document.getElementById('columnsDropdown');
  dd.classList.toggle('show');
  this.classList.toggle('active');
  document.getElementById('filtersPanel').classList.remove('show');
  document.getElementById('filtersBtn').classList.remove('active');
});

document.getElementById('columnsDropdown').addEventListener('change', function(e) {
  if (e.target.type === 'checkbox') {
    columnVisibility[e.target.dataset.col] = e.target.checked;
    renderTable();
  }
});

// ── Filters Panel ───────────────────────────────────────────
document.getElementById('filtersBtn').addEventListener('click', function(e) {
  e.stopPropagation();
  const panel = document.getElementById('filtersPanel');
  panel.classList.toggle('show');
  this.classList.toggle('active');
  document.getElementById('columnsDropdown').classList.remove('show');
  document.getElementById('columnsBtn').classList.remove('active');
});

function applyFilters() {
  const minP = document.getElementById('filterMinPrice').value;
  const maxP = document.getElementById('filterMaxPrice').value;
  const chg = document.getElementById('filterChange').value;
  priceFilter = { min: minP, max: maxP };
  changeFilter = chg || null;
  currentPage = 1;
  renderTable();
  document.getElementById('filtersPanel').classList.remove('show');
  document.getElementById('filtersBtn').classList.remove('active');
}

function clearFilters() {
  document.getElementById('filterMinPrice').value = '';
  document.getElementById('filterMaxPrice').value = '';
  document.getElementById('filterChange').value = '';
  priceFilter = null;
  changeFilter = null;
  currentPage = 1;
  renderTable();
  document.getElementById('filtersPanel').classList.remove('show');
  document.getElementById('filtersBtn').classList.remove('active');
}

// ── Close dropdowns on outside click ────────────────────────
document.addEventListener('click', function() {
  document.getElementById('columnsDropdown').classList.remove('show');
  document.getElementById('columnsBtn').classList.remove('active');
  document.getElementById('filtersPanel').classList.remove('show');
  document.getElementById('filtersBtn').classList.remove('active');
});

// ── Promo Carousel ──────────────────────────────────────────
let currentSlide = 0;
const slides = document.querySelectorAll('.promo-slide');
const dots = document.querySelectorAll('.promo-dot');

function showSlide(n) {
  slides.forEach(s => s.classList.remove('active'));
  dots.forEach(d => d.classList.remove('active'));
  currentSlide = (n + slides.length) % slides.length;
  slides[currentSlide].classList.add('active');
  dots[currentSlide].classList.add('active');
}

function nextSlide() { showSlide(currentSlide + 1); }
function prevSlide() { showSlide(currentSlide - 1); }
function goSlide(n) { showSlide(n); }

let carouselInterval = setInterval(nextSlide, 5000);
document.getElementById('promoBanner').addEventListener('mouseenter', () => clearInterval(carouselInterval));
document.getElementById('promoBanner').addEventListener('mouseleave', () => { carouselInterval = setInterval(nextSlide, 5000); });

// ── Market Summary Accordion ────────────────────────────────
function toggleReadMore() {
  const more = document.getElementById('moreContent');
  const btn = document.getElementById('readMoreBtn');
  const isOpen = more.classList.toggle('show');
  btn.innerHTML = isOpen ? 'Read Less <i class="ri-arrow-up-s-line"></i>' : 'Read More <i class="ri-arrow-down-s-line"></i>';
}

// ── Initial Render ──────────────────────────────────────────
renderTable();
</script>
</body>
</html>
