  if (activeNetwork !== 'all') {
    filtered = filtered.filter(c => c.network === activeNetwork || (activeNetwork === 'more' && !['ethereum','solana','bsc','base'].includes(c.network)));
  }
  if (priceFilter) {
    if (priceFilter.min != null && priceFilter.min !== '') filtered = filtered.filter(c => c.price >= +priceFilter.min);
    if (priceFilter.max != null && priceFilter.max !== '') filtered = filtered.filter(c => c.price <= +priceFilter.max);
  }
  if (changeFilter) {
    if (changeFilter === 'up') filtered = filtered.filter(c => c.change24h >= 0);
    if (changeFilter === 'down') filtered = filtered.filter(c => c.change24h < 0);
    if (changeFilter === 'gt5') filtered = filtered.filter(c => c.change24h >= 5);
    if (changeFilter === 'lt5') filtered = filtered.filter(c => c.change24h <= -5);
  }
  // Sort
  filtered.sort((a, b) => {
    let va = a[activeSort.field];
    let vb = b[activeSort.field];
    if (activeSort.field === 'name') { va = a.name.toLowerCase(); vb = b.name.toLowerCase(); }
    if (activeSort.field === 'supply') { va = a.circulatingSupply; vb = b.circulatingSupply; }
    if (va < vb) return activeSort.dir === 'asc' ? -1 : 1;
    if (va > vb) return activeSort.dir === 'asc' ? 1 : -1;
    return 0;
  });
  filtered.forEach((c, i) => c.displayRank = i + 1);
  filtered.totalCount = filtered.length;
  return filtered;
}

