function renderSparklineSVG(points, isUp) {
  const cls = isUp ? 'up' : 'down';
  const pts = points.split(',');
  return `<svg class="sparkline-svg" viewBox="0 0 120 32" preserveAspectRatio="none">
    <polyline class="${cls}" points="0,${pts[0]} 20,${pts[1]} 40,${pts[2]} 60,${pts[3]} 80,${pts[4]} 100,${pts[5]} 120,${pts[6]}" />
  </svg>`;
}

function renderCoinRow(c) {
  let html = '<tr>';
  const coinBg = c.color;
  if (columnVisibility.rank) html += `<td>${c.displayRank}</td>`;
  if (columnVisibility.name) html += `<td><div class="coin-info"><div class="coin-icon" style="background:${coinBg}">${c.symbol.slice(0,2)}</div><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.symbol}</span></div></td>`;
  if (columnVisibility.price) html += `<td class="price">$${fmtNum(c.price, c.price < 0.01 ? 6 : c.price < 1 ? 4 : 2)}</td>`;
  if (columnVisibility.change1h) html += `<td>${fmtChange(c.change1h)}</td>`;
  if (columnVisibility.change24h) html += `<td>${fmtChange(c.change24h)}</td>`;
  if (columnVisibility.change7d) html += `<td>${fmtChange(c.change7d)}</td>`;
  if (columnVisibility.marketCap) html += `<td class="mcap">${fmtCompact(c.marketCap)}</td>`;
  if (columnVisibility.volume) html += `<td class="vol">${fmtCompact(c.volume)}</td>`;
  if (columnVisibility.supply) html += `<td class="supply">${fmtSupply(c.circulatingSupply, c.supplySymbol)}</td>`;
  if (columnVisibility.sparkline) html += `<td class="sparkline-cell">${renderSparklineSVG(c.sparkline, c.change7d >= 0)}</td>`;
  html += '</tr>';
  return html;
}

function renderTable() {
  const filtered = getFilteredCoins();
  const totalCount = filtered.totalCount || filtered.length;
  const totalPages = Math.ceil(totalCount / rowsPerPage);
  if (currentPage > totalPages) currentPage = totalPages || 1;
