  if (currentPage === 1) {
    html += `<tr class="index-row">
      <td>—</td>
      <td><div class="coin-info"><div class="coin-icon" style="background:var(--blue)">CT</div><span class="coin-name" style="color:var(--blue)">CoinTracker 20 Index</span><span class="coin-symbol">DTFCTP20</span></div></td>
      <td class="price">$154.29</td>
      <td>${fmtChange(0.21)}</td>
      <td>${fmtChange(1.15)}</td>
