      <td class="vol">—</td>
      <td class="supply">—</td>
      <td class="sparkline-cell"></td>
    </tr>`;
  }

  page.forEach(c => { html += renderCoinRow(c); });

  tbody.innerHTML = html;
  renderPagination(totalCount);
  updateColumnHeaders();
}

