function seededRand(seed) {
  let h = 0;
  for (let i = 0; i < seed.length; i++) { h = ((h << 5) - h) + seed.charCodeAt(i); h |= 0; }
  return Math.abs(h) / 2147483647;
}

function generateCoin(rank) {
  const idx = (rank - 1) % coinNames.length;
  const [name, symbol] = coinNames[idx];
  const seedStr = symbol + '_' + rank;
  const r = seededRand(seedStr);
  const rr = seededRand(seedStr + 'x');

  let price;
  if (rank <= 5) {
    price = [75612.78, 2356.00, 1.00, 1.44, 632.59][rank - 1];
  } else if (rank <= 30) {
    price = (0.01 + r * 200);
  } else if (rank <= 80) {
    price = (0.001 + r * 20);
  } else {
    price = (0.00001 + r * 1);
  }

  const h1 = ((r - 0.5) * 4).toFixed(2) * 1;
  const h24 = ((rr - 0.45) * 10).toFixed(2) * 1;
  const d7 = ((r - 0.4) * 18).toFixed(2) * 1;
  const mcap = price * (500000 + r * 2e10);

  if (rank === 1) {
    const btc = coins[0];
    return { ...btc, rank, displayRank: rank };
  }
  if (rank === 2) {
    const eth = coins[1];
    return { ...eth, rank, displayRank: rank };
  }
  if (rank === 3) {
    const usdt = coins[2];
    return { ...usdt, rank, displayRank: rank };
  }
  if (rank <= 20 && rank - 1 < coins.length) {
    const c = coins[rank - 1];
    return { ...c, rank, displayRank: rank };
  }

  const vol = mcap * (0.01 + r * 0.1);
  const csupp = mcap / price;
  const netOpts = ['ethereum','solana','bsc','base','all'];
  const catOpts = ['top','trending','watchlist','prediction','visited','new'];
  const sp = genSparkline(symbol, d7);

  return {
    rank, displayRank: rank, name, symbol, price,
    change1h: h1, change24h: h24, change7d: d7,
    marketCap: mcap, volume: vol,
    circulatingSupply: csupp, supplySymbol: symbol,
    sparkline: sp,
    network: netOpts[Math.floor(r * 5)],
    category: catOpts[Math.floor(rr * 6)],
    color: '#' + Math.floor(r * 0xFFFFFF).toString(16).padStart(6, '0')
  };
}

