const DEFAULT_TOTAL = 8364;

function getFilteredCoins() {
  const isDefaultView = activeCategory === 'top' && activeNetwork === 'all' && !priceFilter && !changeFilter;
  const totalAssets = isDefaultView ? DEFAULT_TOTAL : coins.length;

  if (isDefaultView && activeSort.field === 'rank' && activeSort.dir === 'asc') {
    // For default view, generate coins on demand for current page
    const pageCoins = [];
    const start = (currentPage - 1) * rowsPerPage + 1;
    for (let i = 0; i < rowsPerPage && (start + i) <= DEFAULT_TOTAL; i++) {
      pageCoins.push(generateCoin(start + i));
    }
    pageCoins.totalCount = DEFAULT_TOTAL;
    return pageCoins;
  }

  // For filtered/sorted views, use static dataset
  let filtered = [...coins];
  if (activeCategory !== 'top') {
    filtered = filtered.filter(c => {
      if (activeCategory === 'trending') return c.category === 'trending' || c.rank % 7 === 2;
      if (activeCategory === 'watchlist') return c.rank % 5 === 0 || c.category === 'watchlist';
      if (activeCategory === 'prediction') return c.category === 'prediction' || c.rank % 10 === 3;
      if (activeCategory === 'visited') return c.category === 'visited' || c.rank % 7 === 0;
      if (activeCategory === 'new') return c.category === 'new' || c.rank > 80;
      if (activeCategory === 'more') return c.rank % 3 === 0;
      return true;
    });
  }
  if (activeNetwork !== 'all') {
    filtered = filtered.filter(c => c.network === activeNetwork || (activeNetwork === 'more' && !['ethereum','solana','bsc','base'].includes(c.network)));
  }
  if (priceFilter) {
    if (priceFilter.min != null && priceFilter.min !== '') filtered = filtered.filter(c => c.price >= +priceFilter.min);
    if (priceFilter.max != null && priceFilter.max !== '') filtered = filtered.filter(c => c.price <= +priceFilter.max);
  }
  if (changeFilter) {
    if (changeFilter === 'up') filtered = filtered.filter(c => c.change24h >= 0);
    if (changeFilter === 'down') filtered = filtered.filter(c => c.change24h < 0);
    if (changeFilter === 'gt5') filtered = filtered.filter(c => c.change24h >= 5);
    if (changeFilter === 'lt5') filtered = filtered.filter(c => c.change24h <= -5);
  }
  // Sort
  filtered.sort((a, b) => {
    let va = a[activeSort.field];
    let vb = b[activeSort.field];
    if (activeSort.field === 'name') { va = a.name.toLowerCase(); vb = b.name.toLowerCase(); }
    if (activeSort.field === 'supply') { va = a.circulatingSupply; vb = b.circulatingSupply; }
