      if (activeCategory === 'new') return c.category === 'new' || c.rank > 80;
      if (activeCategory === 'more') return c.rank % 3 === 0;
      return true;
    });
  }
  if (activeNetwork !== 'all') {
    filtered = filtered.filter(c => c.network === activeNetwork || (activeNetwork === 'more' && !['ethereum','solana','bsc','base'].includes(c.network)));
  }
  if (priceFilter) {
    if (priceFilter.min != null && priceFilter.min !== '') filtered = filtered.filter(c => c.price >= +priceFilter.min);
