      if (activeCategory === 'watchlist') return c.rank % 5 === 0 || c.category === 'watchlist';
      if (activeCategory === 'prediction') return c.category === 'prediction' || c.rank % 10 === 3;
      if (activeCategory === 'visited') return c.category === 'visited' || c.rank % 7 === 0;
      if (activeCategory === 'new') return c.category === 'new' || c.rank > 80;
      if (activeCategory === 'more') return c.rank % 3 === 0;
      return true;
    });
  }
  if (activeNetwork !== 'all') {
    filtered = filtered.filter(c => c.network === activeNetwork || (activeNetwork === 'more' && !['ethereum','solana','bsc','base'].includes(c.network)));
  }
  if (priceFilter) {
    if (priceFilter.min != null && priceFilter.min !== '') filtered = filtered.filter(c => c.price >= +priceFilter.min);
    if (priceFilter.max != null && priceFilter.max !== '') filtered = filtered.filter(c => c.price <= +priceFilter.max);
  }
  if (changeFilter) {
    if (changeFilter === 'up') filtered = filtered.filter(c => c.change24h >= 0);
    if (changeFilter === 'down') filtered = filtered.filter(c => c.change24h < 0);
    if (changeFilter === 'gt5') filtered = filtered.filter(c => c.change24h >= 5);
    if (changeFilter === 'lt5') filtered = filtered.filter(c => c.change24h <= -5);
  }
  // Sort
  filtered.sort((a, b) => {
    let va = a[activeSort.field];
    let vb = b[activeSort.field];
    if (activeSort.field === 'name') { va = a.name.toLowerCase(); vb = b.name.toLowerCase(); }
    if (activeSort.field === 'supply') { va = a.circulatingSupply; vb = b.circulatingSupply; }
    if (va < vb) return activeSort.dir === 'asc' ? -1 : 1;
    if (va > vb) return activeSort.dir === 'asc' ? 1 : -1;
    return 0;
  });
  filtered.forEach((c, i) => c.displayRank = i + 1);
  filtered.totalCount = filtered.length;
  return filtered;
}

// ── Render Table ────────────────────────────────────────────
function renderSparklineSVG(points, isUp) {
  const cls = isUp ? 'up' : 'down';
  const pts = points.split(',');
  return `<svg class="sparkline-svg" viewBox="0 0 120 32" preserveAspectRatio="none">
    <polyline class="${cls}" points="0,${pts[0]} 20,${pts[1]} 40,${pts[2]} 60,${pts[3]} 80,${pts[4]} 100,${pts[5]} 120,${pts[6]}" />
  </svg>`;
}

function renderCoinRow(c) {
  let html = '<tr>';
  const coinBg = c.color;
  if (columnVisibility.rank) html += `<td>${c.displayRank}</td>`;
  if (columnVisibility.name) html += `<td><div class="coin-info"><div class="coin-icon" style="background:${coinBg}">${c.symbol.slice(0,2)}</div><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.symbol}</span></div></td>`;
  if (columnVisibility.price) html += `<td class="price">$${fmtNum(c.price, c.price < 0.01 ? 6 : c.price < 1 ? 4 : 2)}</td>`;
  if (columnVisibility.change1h) html += `<td>${fmtChange(c.change1h)}</td>`;
  if (columnVisibility.change24h) html += `<td>${fmtChange(c.change24h)}</td>`;
  if (columnVisibility.change7d) html += `<td>${fmtChange(c.change7d)}</td>`;
  if (columnVisibility.marketCap) html += `<td class="mcap">${fmtCompact(c.marketCap)}</td>`;
  if (columnVisibility.volume) html += `<td class="vol">${fmtCompact(c.volume)}</td>`;
  if (columnVisibility.supply) html += `<td class="supply">${fmtSupply(c.circulatingSupply, c.supplySymbol)}</td>`;
  if (columnVisibility.sparkline) html += `<td class="sparkline-cell">${renderSparklineSVG(c.sparkline, c.change7d >= 0)}</td>`;
  html += '</tr>';
  return html;
}

function renderTable() {
  const filtered = getFilteredCoins();
  const totalCount = filtered.totalCount || filtered.length;
  const totalPages = Math.ceil(totalCount / rowsPerPage);
  if (currentPage > totalPages) currentPage = totalPages || 1;
  const isDefaultView = activeCategory === 'top' && activeNetwork === 'all' && !priceFilter && !changeFilter;

  let page;
  if (isDefaultView && activeSort.field === 'rank' && activeSort.dir === 'asc') {
    page = filtered;
  } else {
    const start = (currentPage - 1) * rowsPerPage;
    page = filtered.slice(start, start + rowsPerPage);
  }

  const tbody = document.getElementById('tableBody');
  let html = '';

  // Index row (only on page 1)
  if (currentPage === 1) {
    html += `<tr class="index-row">
      <td>—</td>
      <td><div class="coin-info"><div class="coin-icon" style="background:var(--blue)">CT</div><span class="coin-name" style="color:var(--blue)">CoinTracker 20 Index</span><span class="coin-symbol">DTFCTP20</span></div></td>
      <td class="price">$154.29</td>
      <td>${fmtChange(0.21)}</td>
      <td>${fmtChange(1.15)}</td>
      <td>${fmtChange(4.97)}</td>
      <td class="mcap">—</td>
      <td class="vol">—</td>
      <td class="supply">—</td>
      <td class="sparkline-cell"></td>
    </tr>`;
  }

  page.forEach(c => { html += renderCoinRow(c); });

  tbody.innerHTML = html;
  renderPagination(totalCount);
  updateColumnHeaders();
}

function renderPagination(totalItems) {
  const totalPages = Math.ceil(totalItems / rowsPerPage);
  const el = document.getElementById('pagination');
  let html = '';
  html += `<button class="page-btn" onclick="goPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled' : ''}><i class="ri-arrow-left-s-line"></i></button>`;

  const maxBtns = 7;
  let startP = Math.max(1, currentPage - 3);
  let endP = Math.min(totalPages, startP + maxBtns - 1);
  if (endP - startP < maxBtns - 1) startP = Math.max(1, endP - maxBtns + 1);

  if (startP > 1) { html += `<button class="page-btn" onclick="goPage(1)">1</button>`; if (startP > 2) html += `<span class="page-info">…</span>`; }
  for (let i = startP; i <= endP; i++) {
    html += `<button class="page-btn${i === currentPage ? ' active' : ''}" onclick="goPage(${i})">${i}</button>`;
  }
  if (endP < totalPages) { if (endP < totalPages - 1) html += `<span class="page-info">…</span>`; html += `<button class="page-btn" onclick="goPage(${totalPages})">${totalPages}</button>`; }

  html += `<button class="page-btn" onclick="goPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled' : ''}><i class="ri-arrow-right-s-line"></i></button>`;
  html += `<span class="page-info">Showing ${((currentPage-1)*rowsPerPage+1).toLocaleString()}–${Math.min(currentPage*rowsPerPage, totalItems).toLocaleString()} of ${totalItems.toLocaleString()} assets</span>`;
  el.innerHTML = html;
}

